Field guidance:
- historical_evidence and failed_approaches: only records returned by a tool, with the status as recorded; empty lists
  if nothing relevant was returned.
- testability.p_testable: probability that the question can be answered with the stated data at useful statistical power.
- prior_work.already_answered: whether retrieved earlier work already answered substantially the same question.
  Use "unknown" if no earlier work was retrieved. List identifiers you relied on in prior_work.cited.
- predicted_outcome: probabilities (summing to 1) of what a competent test of the question as posed would conclude:
  supported, rejected (adequately powered null), untestable (cannot be tested with this data), artifact (apparent
  effect produced by a flaw), uncertain (inconclusive or inadequately tested).
- decision: proceed, proceed_with_changes (state the changes in design), or do_not_proceed.
- design: a pre-registration-quality plan even if the decision is do_not_proceed (then describe the minimum viable test).

{
 "research_concepts": ["defensive suppression", "counter strategy", "suppression-conditional recommended mix", "adherence to recommended play-type mix", "playoff series winning"],
 "methodological_questions": [
  "Does adherence to a suppression-conditional recommended mix predict series winning, beyond team strength?",
  "How should adherence be defined and measured from play-by-play-derived possession records?",
  "How many series units are needed to detect an adherence-outcome association, given 54 available series?",
  "Can the recommended mix be derived without using the outcomes it is evaluated against?"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-APPM-016",
   "status_as_recorded": "rejected",
   "finding": "Possession-level test of whether possessions on the engine's recommended PT score more than other PTs within the series. Test A +0.140 PPP [0.084,0.196]; Test B DiD +0.090 [0.041,0.141]; Test C two-way FE gamma +0.0088, SE 0.0239, p=0.7139 on 504 cells from 74 team-series pairs. Recorded failure type B_powered_null; A and B were attributed to the engine picking high-PPP play types."
  },
  {
   "id": "FAM:SF-APPS-023",
   "status_as_recorded": "rejected",
   "finding": "Matchup-specific (non-CUT) BEST counters vs a feasibility-weighted league mix. All-play gap +0.269 (p=0.0000, n=283), but non-CUT gap +0.010 (p=0.1709, n=136) and L3 matchup non-CUT gap +0.001 (p=0.3277, n=47). Headline result recorded as CUT-driven. Limitations recorded: selection or regression to the mean; small sample. Recorded failure type B_powered_null."
  },
  {
   "id": "FAM:SF-APPM-001",
   "status_as_recorded": "supported",
   "finding": "Holdout game-team rows (908 rows, 454 games): teams whose play-type mix is closer to the model's recommended mix score higher ORtg. Raw gap +5.18 ORtg; strength-controlled gap +3.27 ORtg (+0.0193 vs -0.0134 PPP residual). No CI stated. Validation recorded as same-pipeline. Outcome is game efficiency, not series winning."
  },
  {
   "id": "FAM:SF-APPS-017",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Descriptive comparison of observed vs recommended play-type mix in single 2025-26 playoff Game 1s (4 games x 2 offenses, about 100 possessions per game). Average gap across leverage buckets 4.5 to 24.0 pp; 4 of 8 sides best matched opener #3, not rank-1. No outcome comparison. Recorded mechanism E_unclear; CUT and PNR muted by tagger floor."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-APPM-016",
   "what_failed": "Possession-level test that the engine's recommended play type outscores other play types within a series",
   "why": "Strictest fixed-effects test was null (gamma +0.0088, p=0.71). The apparent positive effects in A and B were explained by the engine selecting high-PPP play types, so the recommendation tracked inherent efficiency rather than adding to it."
  },
  {
   "id": "FAM:SF-APPS-023",
   "what_failed": "Showing that matchup-specific (non-CUT) recommended counters beat a league mix that ignores game state",
   "why": "After removing CUT plays, the gap was small and not significant (non-CUT +0.010, p=0.17; L3 +0.001, p=0.33). The headline effect was recorded as driven by CUT plays and limited by selection or regression to the mean and small sample."
  },
  {
   "id": "FAM:SF-APPS-017",
   "what_failed": "Measuring adherence to the recommended opener in a single game",
   "why": "Recorded as E_unclear with a mechanical-floor concern (CUT and PNR muted by tagger floor). Single-game horizon and no outcome comparison, so it could not link adherence to winning."
  }
 ],
 "evidence_establishes": [
  "Earlier project tests of recommended-mix adherence at the possession and matchup level were null or confounded once selection on high-efficiency play types was addressed (APPM-016, APPS-023).",
  "The only positive result (APPM-001) is an efficiency association at game-team level, which the retrieved record does not connect to series winning.",
  "Adherence measurement from tagged play types is subject to a tagger floor that mutes some play types (APPS-017).",
  "Selection of recommended plays on efficiency is a documented confounder in this project's earlier tests (APPM-016, APPS-023)."
 ],
 "evidence_does_not_establish": [
  "Any association between adherence and series winning. No retrieved record tests series-level outcomes.",
  "Whether a suppression-conditional mix (as opposed to a PPP-maximising mix) adds predictive value beyond team strength.",
  "Whether the 54 available series give adequate power for the question.",
  "Anything about the 2025-26 playoffs beyond single-game descriptions, since the data were incomplete on the question date."
 ],
 "own_inferences": [
  "A series-level binary test with about 54 units has low power unless the effect is large, so a null is the most likely result even if a small real effect exists.",
  "Adherence is probably correlated with team quality and play-type efficiency, so a raw adherence-win association would mainly reflect strength and selection.",
  "Because the recommender is built from play-type efficiency and team strength, using the same data to train and evaluate it risks leakage that inflates apparent adherence effects.",
  "Using 2025-26 playoff data before completion (2026-06-21) would introduce partial-data bias."
 ],
 "uncertainties": [
  "The series count (54) is recorded as available units, not confirmed as completed series with final outcomes.",
  "The formula for the suppression-conditional recommended mix and the adherence metric are not given in the retrieved records.",
  "Fields for 'observed_notes' and validation evidence are NOT_RECORDED in APPM-016 and APPS-017, so the strength of their conclusions is unverified.",
  "The retrieval returned no record on series-level outcomes or on a prior series-winning test."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The retrieved records show that the project's earlier possession-level and matchup-level adherence tests were null or confounded by selection on efficiency, and the one positive result was at game-team efficiency level, not series winning. Without that evidence, the question might have looked testable with 54 series. With it, I judged that a series-winning test would be underpowered and confounded by team strength and selection, so I recommend against proceeding as posed."
 },
 "testability": {
  "p_testable": 0.2,
  "blocking_constraints": [
   {"code": "SAMPLE_SIZE_POWER", "text": "54 series units give low power for a binary series-winning outcome, especially after adjusting for team strength."},
   {"code": "RTM_SELECTION", "text": "Recommended plays are selected on efficiency, so adherence partly proxies for high-PPP play types (APPM-016, APPS-023)."},
   {"code": "MEASURE_RELIABILITY", "text": "Play-type tagging has a floor that mutes CUT and PNR, so adherence measurement is unreliable for some categories (APPS-017)."}
  ]
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": ["FAM:SF-APPM-016", "FAM:SF-APPS-023", "FAM:SF-APPM-001", "FAM:SF-APPS-017"],
  "summary": "Earlier work covers related but not identical questions. Possession- and matchup-level adherence tests were null or confounded (APPM-016 rejected; APPS-023 rejected after removing CUT). A game-level efficiency association was supported (APPM-001). A single-game conformance measure was descriptive only (APPS-017). None tests whether adherence predicts series winning, so the question is partly but not substantially answered."
 },
 "risks": [
  {"code": "SAMPLE_SIZE_POWER", "text": "About 54 series units are unlikely to detect a modest adherence effect on a binary outcome."},
  {"code": "RTM_SELECTION", "text": "Recommendations chosen for high PPP make adherence look predictive by picking efficient play types, as in APPM-016."},
  {"code": "CONFOUNDING", "text": "Team strength, pace, and roster quality drive both adherence and series wins; the retrieved records show these were not fully separated."},
  {"code": "OUTCOME_DERIVED_LABEL", "text": "If the suppression-conditional mix is derived from outcome-correlated data, the recommender is partly trained on the target."},
  {"code": "LEAKAGE_LOOKAHEAD", "text": "Using full-series information to define adherence or the recommended mix could leak future outcomes into the predictor."},
  {"code": "MEASURE_RELIABILITY", "text": "Tagger floor mutes CUT and PNR, making adherence measurement unreliable for those categories (APPS-017)."},
  {"code": "MULTIPLE_TESTING", "text": "Several adherence definitions, horizons, and subsets (all-play, non-CUT, L3 matchup) raise the chance of a spurious significant result, as seen in APPS-023."},
  {"code": "EXPOSURE_SPARSITY", "text": "Matchup-specific or leverage-specific mix cells are sparse, as in the n=47 L3 non-CUT cell (APPS-023)."},
  {"code": "BASE_RATE", "text": "Series outcomes are close to balanced for most matchups, so an adherence effect needs to be large to show up."},
  {"code": "DRIFT_NONSTATIONARITY", "text": "Playoff play-type mix and tagging conventions may change across 2022-23 to 2025-26, and the 2025-26 playoffs were incomplete on the question date."}
 ],
 "predicted_outcome": {
  "supported": 0.05,
  "rejected": 0.45,
  "untestable": 0.05,
  "artifact": 0.1,
  "uncertain": 0.35
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "Within-series association between adherence to the suppression-conditional recommended mix and series win, conditional on pre-series team strength (for example, pre-series net rating and roster strength), reported as a log-odds ratio with CI. Not to be interpreted as causal.",
  "unit": "Team-series (each series contributes two team-perspective rows, which are not independent; use series-clustered inference).",
  "sample": "Only completed series with final outcomes from 2022-23 to 2024-25 playoffs, plus any 2025-26 series completed before the data freeze (after 2026-06-21 if using full playoffs). The 54-unit count must be confirmed. Partial 2025-26 playoff data must be excluded.",
  "power": "Not established. With about 54 series, detectable effects are likely large (for example, odds ratio near or above 2). A power calculation must be run before analysis; if it shows less than 80% power for a plausible effect, the test cannot be justified.",
  "controls": "Pre-series team strength; opponent strength; rest; injuries; home court; prior-season recommended mix. The recommender must be fit on earlier seasons only, with adherence computed from play-type shares of the holdout series.",
  "falsification": "Pre-register a negative control: adherence to the recommended mix predicting a non-target outcome (for example, pre-series rank), and a placebo: the mix from a random or scrambled recommender. The main claim fails if the placebo shows a similar association.",
  "multiplicity": "Pre-register one primary adherence definition and one primary model. Treat CUT-excluded and matchup-specific variants as secondary and adjust for them (for example, Holm).",
  "decision_rule": "Support requires a positive, pre-registered primary association with CI excluding no effect, surviving the team-strength adjustment and placebo test. Otherwise report a null or inconclusive result. Do not use post hoc subsets as the basis for a claim.",
  "data_version": "Freeze the dataset before 2026-06-21 using only completed 2022-23 to 2024-25 playoff series; record the play-by-play and tagging version. Exclude any incomplete 2025-26 playoff series."
 }
}

